sys_script.script:
(function executeRule(current, previous) {

    // Only check when a new complaint is created
    if (!current.isNewRecord()) {
        return;
    }

    // Need a description to compare
    if (current.description.nil()) {
        return;
    }

    var newDescription = (current.description + '').toLowerCase().trim();

    // Search recent complaints
    var gr = new GlideRecord('x_1919740_societ_1_society_complaint_case');
    gr.addQuery('sys_id', '!=', current.sys_id);
    gr.addQuery('active', true);
    gr.orderByDesc('sys_created_on');
    gr.setLimit(20);
    gr.query();

    while (gr.next()) {

        var oldDescription = (gr.description + '').toLowerCase().trim();

        // Simple keyword comparison
        var newWords = newDescription.split(/\s+/);
        var oldWords = oldDescription.split(/\s+/);

        var matchCount = 0;

        for (var i = 0; i < newWords.length; i++) {

            if (newWords[i].length < 4) {
                continue;
            }

            if (oldDescription.indexOf(newWords[i]) > -1) {
                matchCount++;
            }
        }

        // If several meaningful words match, mark as duplicate
        if (matchCount >= 3) {

            current.duplicate_case = gr.sys_id;

            break;
        }
    }

})(current, previous);
